-- Recipe images (owner report 2026-11-12: recipe photos load very slowly). The 229 recipe photos were 1264x848 PNGs of
-- 0.4-2.8 MB each (254 MB in total). They were re-encoded as 900 px progressive JPEG (quality 80, about 90 KB each,
-- 20.5 MB in total, visually identical) and uploaded next to the originals under assets/recipes-opt/ with a one-year
-- cache. This points each recipe at its optimized copy; a row whose URL changed since the review is left alone.
-- The original PNGs stay in storage. admin_recipes is CDC enrolled and writer guarded.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public' AND table_name = 'admin_recipes') <> 1 THEN
    RAISE EXCEPTION 'RECIPE_IMAGES_GUARD_MISSING'; END IF;
END $$;
